define('ML_APP',true);define('ML_ROOT',__DIR__.'/..');require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/PanSou.php';function pma_log(array $a,$b=0){try{\Core\CacheStore::writeSyncLog('cron:pan_match_auto',array($a),(int)$b);}catch(\Throwable $c){error_log('[pan_match_auto] write log failed: '.$c->getMessage());}}$limit=20;$reset=false;$retryDays=7;$quiet=false;foreach(array_slice(isset($argv)?$argv:array(),1)as $arg){$arg=(string)$arg;if(strpos($arg,'--limit=')===0){$limit=max(1,min(50,(int)substr($arg,8)));}elseif(strpos($arg,'--retry-days=')===0){$retryDays=max(0,(int)substr($arg,13));}elseif($arg==='--reset'){$reset=true;}elseif($arg==='--quiet'||$arg==='-q'){$quiet=true;}}$cronCfg=\Core\Config::get('cron',array());$enabled=true;if(isset($cronCfg['match_auto_enabled'])){$v=$cronCfg['match_auto_enabled'];if($v==='0'||$v===0||$v===false||$v==='false'){$enabled=false;}}if(!$enabled){if(!$quiet){fwrite(STDOUT,"[pan_match_auto] 后台配置已关闭（cron.match_auto_enabled=0），跳过。\n");}pma_log(array('status'=>'disabled','at'=>date('Y-m-d H:i:s'),'message'=>'后台配置已关闭（cron.match_auto_enabled=0）',));exit(0);}$lockFile=ML_ROOT.'/config/pan_match_auto.lock';$lockFp=@fopen($lockFile,'c');if(!$lockFp||!@flock($lockFp,LOCK_EX|LOCK_NB)){if(!$quiet){fwrite(STDOUT,"[pan_match_auto] 已有实例在运行（lock=".$lockFile."），跳过。\n");}exit(0);}@ftruncate($lockFp,0);@fwrite($lockFp,(string)getmypid());@fflush($lockFp);$t0=microtime(true);try{$rep=\Core\PanSou::autoMatch($limit,$reset,$retryDays);}catch(\Throwable $e){@flock($lockFp,LOCK_UN);@fclose($lockFp);fwrite(STDERR,"[pan_match_auto] 异常：".$e->getMessage()."\n");exit(1);}$ms=(int)round((microtime(true)-$t0)*1000);if(empty($rep['ok'])){if(!$quiet){fwrite(STDOUT,"[pan_match_auto] 跳过：".(isset($rep['reason'])?$rep['reason']:'不可用')."\n");}pma_log